import React from "react"
import "./BannerArea.css"

const Result = (props) => {
    const {professor, onChangeProfessor} = props;
    return (
        <>
            <div className={"result"} onClick={() => onChangeProfessor(professor.endpoint)}>
               {professor.name}
            </div>
        </>
    )
};

export default Result;
